class ContaBancaria:
    def __init__(self, saldo_inicial=0.0):
        self._saldo = saldo_inicial
    def depositar(self, valor):
        self._saldo += valor
    def sacar(self, valor):
        if self._saldo >= valor:
            self._saldo -= valor
            return True
        return False
    def saldo(self):
        return self._saldo

